def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def as_point(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            a, b = x[0], x[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [int(a), int(b)]
        if isinstance(x, dict):
            for k1, k2 in (("x", "y"), ("row", "col"), ("r", "c")):
                if k1 in x and k2 in x and isinstance(x[k1], (int, float)) and isinstance(x[k2], (int, float)):
                    return [int(x[k1]), int(x[k2])]
        return None

    def deep_points(obj, out, limit=200):
        if limit <= 0:
            return
        p = as_point(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                deep_points(v, out, limit - 1)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                deep_points(v, out, limit - 1)

    def find_first_point_keys(d, keys):
        for k in keys:
            if isinstance(d, dict) and k in d:
                p = as_point(d.get(k))
                if p is not None:
                    return p
        return None

    def get_grid_size(obs):
        for k in ("grid_size", "size", "board_size", "map_size", "dimensions"):
            v = obs.get(k)
            if isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float)):
                return int(v[0]), int(v[1])
            if isinstance(v, dict):
                p = as_point(v)
                if p is not None:
                    return p[0], p[1]
        w = obs.get("width")
        h = obs.get("height")
        if isinstance(w, (int, float)) and isinstance(h, (int, float)):
            return int(w), int(h)
        return None

    def get_self_pos(obs):
        keys = (
            "agent_pos", "agent", "self_pos", "self", "position", "pos", "me",
            "player_pos", "player", "location", "loc", "current_pos", "current"
        )
        p = find_first_point_keys(obs, keys)
        if p is not None:
            return p
        for k in ("agents", "players", "units", "entities"):
            v = obs.get(k)
            if isinstance(v, (list, tuple)) and len(v) > 0:
                # Try entries that look like dicts with role/self flags.
                for e in v:
                    if isinstance(e, dict) and (e.get("is_self") or e.get("self") or e.get("controlled")):
                        p = as_point(e.get("pos") or e.get("position") or e.get("loc") or e)
                        if p is not None:
                            return p
                # Otherwise first point-like entry.
                for e in v:
                    p = as_point(e)
                    if p is not None:
                        return p
                    if isinstance(e, dict):
                        p = find_first_point_keys(e, ("pos", "position", "loc", "xy"))
                        if p is not None:
                            return p
        return None

    def categorize_points(obs):
        good = []
        bad = []
        neutral = []
        for k in ("resources", "resource_positions", "targets", "target_positions", "food", "items", "collectibles", "capsules"):
            deep_points(obs.get(k), good)
        for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "hazards", "threats", "projectiles"):
            deep_points(obs.get(k), bad)
        for k in ("territory", "frontier", "neutral", "unknown", "unseen", "explored", "visited"):
            deep_points(obs.get(k), neutral)
        # territory grids / maps: infer points from cell lists if structured
        for k in ("grid", "map", "board", "state"):
            v = obs.get(k)
            if isinstance(v, dict):
                if any(isinstance(v.get(t), (list, tuple)) for t in ("resources", "enemies", "targets")):
                    deep_points(v.get("resources"), good)
                    deep_points(v.get("enemies"), bad)
                    deep_points(v.get("targets"), good)
        return good, bad, neutral

    def nearest(pos, pts):
        best = None
        best_d = 10**9
        for p in pts:
            d = abs(p[0] - pos[0]) + abs(p[1] - pos[1])
            if d < best_d:
                best_d = d
                best = p
        return best, best_d

    def move_toward(pos, target):
        if target is None:
            return 0, 0
        dx = 0 if target[0] == pos[0] else (1 if target[0] > pos[0] else -1)
        dy = 0 if target[1] == pos[1] else (1 if target[1] > pos[1] else -1)
        return dx, dy

    pos = get_self_pos(observation)
    if pos is None:
        return [0, 0]

    grid = get_grid_size(observation)
    good, bad, neutral = categorize_points(observation)

    # Also consider generic "objective" fields.
    for k in ("objective", "objectives", "goal", "goals", "destinations", "waypoints"):
        deep_points(observation.get(k), good)

    # Basic scoring over 9 moves.
    best_move = (0, 0)
    best_score = -10**18

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx = pos[0] + dx
            ny = pos[1] + dy
            score = 0

            # Prefer movement over idle when useful.
            if dx != 0 or dy != 0:
                score += 1

            # Toward nearest good item.
            tg, dg = nearest([nx, ny], good)
            if tg is not None:
                score += max(0, 40 - 3 * dg)

            # Away from nearest bad item.
            tb, db = nearest([nx, ny], bad)
            if tb is not None:
                score -= max(0, 50 - 4 * db)
                if db <= 1:
                    score -= 100

            # Territory control: explore neutral/unknown.
            tn, dn = nearest([nx, ny], neutral)
            if tn is not None:
                score += max(0, 14 - dn)

            # Border avoidance if grid known.
            if grid is not None:
                w, h = grid
                if nx < 0 or ny < 0 or nx >= w or ny >= h:
                    score -= 1000
                else:
                    edge = min(nx, ny, w - 1 - nx, h - 1 - ny)
                    score += edge

            # Small tie-breaker: prefer diagonals for coverage.
            if dx != 0 and dy != 0:
                score += 1

            if score > best_score:
                best_score = score
                best_move = (dx, dy)

    return [clamp(best_move[0]), clamp(best_move[1])]

